HINDUSTAN_TIMES_LOGO_DATA_URI = 'data:image/png;base64,'
ECONOMIC_TIMES_LOGO_DATA_URI = 'data:image/png;base64,'
BOMBAY_TIMES_LOGO_DATA_URI = 'data:image/png;base64,'
DNA_LOGO_DATA_URI = 'data:image/png;base64,'
TIMES_OF_INDIA_LOGO_DATA_URI = 'data:image/png;base64,'
MID_DAY_LOGO_DATA_URI = 'data:image/png;base64,'

# ── Soft-grey versions of the Hush “Featured In” logos ───────────────────────
# Maps the darkest logo pixels to #707070 and keeps white pixels white.
# Because the PNG pixels are changed directly, the result is more reliable in
# email clients than using CSS filters such as grayscale() or opacity.
FEATURED_LOGO_DARKEST_GRAY = 112


def convert_logo_to_soft_gray(data_uri, darkest=FEATURED_LOGO_DARKEST_GRAY):
    """Return a grey-toned PNG data URI while preserving transparency."""
    uri_prefix, encoded_image = data_uri.split(",", 1)
    image = Image.open(
        io.BytesIO(base64.b64decode(encoded_image))
    ).convert("RGBA")

    luminance = ImageOps.grayscale(image)
    softened = luminance.point(
        lambda value: darkest + ((255 - darkest) * value // 255)
    )
    alpha = image.getchannel("A")
    grey_image = Image.merge("RGBA", (softened, softened, softened, alpha))

    output = io.BytesIO()
    grey_image.save(output, format="PNG", optimize=True)
    return f"{uri_prefix},{base64.b64encode(output.getvalue()).decode('ascii')}"


