# ── Helpers ──────────────────────────────────────────────────────────────────
def clear_generated_footer():
    """Clear the previous result when the selected brand changes."""
    st.session_state.pop("generated_footer", None)
    st.session_state.pop("open_footer_once", None)


def validate_inputs(brand, first_name, last_name, phone, email_address, job_title):
    """Validate form inputs using the selected brand's existing rules."""
    errors = []

    fn = first_name.strip()
    if not fn:
        errors.append("First Name cannot be empty.")
    elif len(fn.split()) > 2:
        errors.append("First Name should be one or two words only.")

    ln = last_name.strip()
    if not ln:
        errors.append("Last Name cannot be empty.")
    elif len(ln.split()) > 2:
        errors.append("Last Name should be one or two words only.")

    if brand == "Flo":
        ph = phone.strip()
        if not ph:
            errors.append("Phone Number cannot be empty.")
        elif not re.fullmatch(r"\d{10}", ph):
            errors.append(
                "Please enter a valid 10-digit phone number "
                "(digits only, no spaces or dashes)."
            )
    else:
        ph = re.sub(r"\s+", "", phone)
        if not ph:
            errors.append("Phone Number cannot be empty.")
        elif not re.fullmatch(r"\d{10}", ph):
            errors.append(
                "Please enter a valid 10-digit phone number "
                "(digits only; spaces are allowed)."
            )

    em = email_address.strip()
    if not em:
        errors.append("Email ID cannot be empty.")
    elif brand == "Flo" and not em.endswith("@flomattress.com"):
        errors.append(
            "Please enter a valid Flo Mattress email address "
            "(must end with @flomattress.com)."
        )
    elif brand == "Hush" and not re.fullmatch(
        r"[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@hush\.in",
        em,
        flags=re.IGNORECASE,
    ):
        errors.append("Please enter a valid Hush email address ending in @hush.in.")

    jt = job_title.strip()
    if not jt:
        errors.append("Job Title cannot be empty.")

    cleaned = {
        "first_name": fn,
        "last_name": ln,
        "phone": ph,
        "email": em,
        "job_title": jt,
    }
    return errors, cleaned


def replace_tokens(template, replacements):
    """Replace all footer-template tokens with their final values."""
    output = template
    for token, value in replacements.items():
        output = output.replace(token, value)
    return output


def build_flo_footer_html(details):
    """Insert employee details into the original Flo footer template."""
    full_name = f"{details['first_name']} {details['last_name']}"
    phone = details["phone"]

    replacements = {
        "{{FULL_NAME}}": html.escape(full_name),
        "{{JOB_TITLE}}": html.escape(details["job_title"]),
        "{{EMAIL}}": html.escape(details["email"]),
        "{{PHONE_RAW}}": phone,
        "{{PHONE_FORMATTED}}": f"{phone[:3]} {phone[3:6]} {phone[6:]}",
    }
    return replace_tokens(FLO_HTML_TEMPLATE, replacements)


def build_hush_footer_html(details):
    """Insert employee details and embedded assets into the Hush footer template."""
    full_name = f"{details['first_name']} {details['last_name']}"
    phone = details["phone"]

    replacements = {
        "{{FULL_NAME}}": html.escape(full_name),
        "{{JOB_TITLE}}": html.escape(details["job_title"]),
        "{{EMAIL}}": html.escape(details["email"]),
        "{{PHONE_RAW}}": phone,
        "{{PHONE_FORMATTED}}": f"{phone[:3]} {phone[3:6]} {phone[6:]}",
        "{{HUSH_LOGO_URI}}": HUSH_LOGO_DATA_URI,
        "{{PHONE_ICON_URI}}": PHONE_ICON_DATA_URI,
        "{{EMAIL_ICON_URI}}": EMAIL_ICON_DATA_URI,
        "{{WEB_ICON_URI}}": WEB_ICON_DATA_URI,
        "{{FACEBOOK_ICON_URI}}": FACEBOOK_ICON_DATA_URI,
        "{{TWITTER_ICON_URI}}": TWITTER_ICON_DATA_URI,
        "{{INSTAGRAM_ICON_URI}}": INSTAGRAM_ICON_DATA_URI,
        "{{HINDUSTAN_TIMES_LOGO_URI}}": HINDUSTAN_TIMES_LOGO_GREY_DATA_URI,
        "{{ECONOMIC_TIMES_LOGO_URI}}": ECONOMIC_TIMES_LOGO_GREY_DATA_URI,
        "{{BOMBAY_TIMES_LOGO_URI}}": BOMBAY_TIMES_LOGO_GREY_DATA_URI,
        "{{DNA_LOGO_URI}}": DNA_LOGO_GREY_DATA_URI,
        "{{TIMES_OF_INDIA_LOGO_URI}}": TIMES_OF_INDIA_LOGO_GREY_DATA_URI,
        "{{MID_DAY_LOGO_URI}}": MID_DAY_LOGO_GREY_DATA_URI,
    }
    return replace_tokens(HUSH_HTML_TEMPLATE, replacements)


def build_footer_html(brand, details):
    """Build the footer selected in the brand toggle."""
    if brand == "Flo":
        return build_flo_footer_html(details)
    return build_hush_footer_html(details)


def build_open_panel(html_output, auto_open, brand):
    """Create a small panel that opens the generated HTML in a new browser tab."""
    encoded = base64.b64encode(html_output.encode("utf-8")).decode("ascii")
    encoded_js = json.dumps(encoded)
    auto_open_js = "true" if auto_open else "false"
    accent_color = "#004EA8" if brand == "Flo" else "#250641"
    button_text_js = json.dumps(f"Open generated {brand} footer")

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<style>
    body {{
        margin: 0;
        padding: 8px 0;
        font-family: Arial, sans-serif;
        background: transparent;
    }}
    a {{
        display: inline-block;
        padding: 9px 14px;
        border-radius: 8px;
        background: {accent_color};
        color: white;
        text-decoration: none;
        font-size: 14px;
        font-weight: 600;
    }}
    #status {{
        margin-left: 10px;
        font-size: 12px;
        color: #60646c;
    }}
</style>
</head>
<body>
    <a id="open-footer" href="#" target="_blank" rel="noopener"></a>
    <span id="status">Preparing footer…</span>

    <script>
        const encodedHtml = {encoded_js};
        const buttonText = {button_text_js};
        const binary = atob(encodedHtml);
        const bytes = new Uint8Array(binary.length);

        for (let i = 0; i < binary.length; i++) {{
            bytes[i] = binary.charCodeAt(i);
        }}

        const blob = new Blob([bytes], {{ type: "text/html;charset=utf-8" }});
        const footerUrl = URL.createObjectURL(blob);
        const openLink = document.getElementById("open-footer");
        const status = document.getElementById("status");

        openLink.textContent = buttonText;
        openLink.href = footerUrl;
        status.textContent = "Ready. Click the button if a new tab did not open.";

        if ({auto_open_js}) {{
            const popup = window.open(footerUrl, "_blank");
            if (popup) {{
                popup.opener = null;
                status.textContent = "Opened in a new tab.";
            }} else {{
                status.textContent = "Your browser blocked the pop-up. Click the button.";
            }}
        }}
    </script>
</body>
</html>"""


# ── App header and brand toggle ───────────────────────────────────────────────
st.title("📧 Flo & Hush Email Footer Generator")
st.markdown(
    "Select the brand, enter the employee details, and generate the corresponding email footer."
)

selected_brand = st.radio(
    "Select footer brand",
    options=["Flo", "Hush"],
    horizontal=True,
    key="selected_brand",
    on_change=clear_generated_footer,
)

brand_email_domain = "@flomattress.com" if selected_brand == "Flo" else "@hush.in"
st.caption(
    f"Currently generating the **{selected_brand}** footer. "
    f"The email address must end in **{brand_email_domain}**."
)
st.divider()


# ── Form fields ───────────────────────────────────────────────────────────────
with st.form(f"{selected_brand.lower()}_footer_form"):
    first_name = st.text_input(
        "First Name",
        key=f"{selected_brand.lower()}_first_name",
    )
    last_name = st.text_input(
        "Last Name",
        key=f"{selected_brand.lower()}_last_name",
    )
    phone = st.text_input(
        "Phone Number",
        help="Enter a 10-digit Indian mobile number.",
        key=f"{selected_brand.lower()}_phone",
    )
    email_address = st.text_input(
        "Email ID",
        help=f"Must end in {brand_email_domain}",
        key=f"{selected_brand.lower()}_email",
    )
    job_title = st.text_input(
        "Job Title",
        key=f"{selected_brand.lower()}_job_title",
    )

    submitted = st.form_submit_button(
        f"Generate and open my {selected_brand} email footer",
        type="primary",
    )


# ── Generate selected footer ──────────────────────────────────────────────────
if submitted:
    errors, details = validate_inputs(
        selected_brand,
        first_name,
        last_name,
        phone,
        email_address,
        job_title,
    )

    if errors:
        st.session_state.pop("generated_footer", None)
        st.session_state.pop("open_footer_once", None)
        for error_message in errors:
            st.error(error_message)
    else:
        html_output = build_footer_html(selected_brand, details)
        full_name = f"{details['first_name']} {details['last_name']}"
        safe_file_stem = re.sub(r"[^A-Za-z0-9_-]+", "_", full_name).strip("_")

        st.session_state.generated_footer = {
            "html": html_output,
            "full_name": full_name,
            "brand": selected_brand,
            "file_name": (
                f"{safe_file_stem or selected_brand}_"
                f"{selected_brand}_Footer.html"
            ),
        }
        st.session_state.open_footer_once = True


# Keep the generated result available after download clicks and reruns.
generated = st.session_state.get("generated_footer")
if generated and generated.get("brand") == selected_brand:
    auto_open = bool(st.session_state.pop("open_footer_once", False))

    st.iframe(
        build_open_panel(
            generated["html"],
            auto_open=auto_open,
            brand=generated["brand"],
        ),
        height=76,
    )

    st.success(
        f"✅ {generated['brand']} footer generated for "
        f"**{generated['full_name']}**!"
    )
    st.info(
        "**In the generated footer tab:**\n\n"
        "1. Press **Ctrl + A** (Windows/Linux) or **Cmd + A** (Mac) to select everything.\n"
        "2. Press **Ctrl + C** / **Cmd + C** to copy.\n"
        "3. Open **Gmail → Settings (⚙️) → See all settings → General**.\n"
        "4. Scroll to **Signature**, click inside the signature box, and paste.\n"
        "5. Scroll to the bottom and click **Save Changes**."
    )

    st.download_button(
        label=f"⬇️ Download the generated {generated['brand']} HTML file",
        data=generated["html"],
        file_name=generated["file_name"],
        mime="text/html",
        on_click="ignore",
    )

    with st.expander(f"Preview the generated {generated['brand']} footer"):
        preview_height = 720 if generated["brand"] == "Flo" else 560
        st.iframe(generated["html"], height=preview_height)
